policy:
{
  // Device posture, evaluated by Tailground's own layer (its reading of the
  // syntax, not Tailscale's code). Right now every admin device reaches prod.
  //
  //   1. Define "posture:corp" below as node:os == 'macos' AND
  //      node:tsVersion >= '1.80'.
  //   2. Add "srcPosture": ["posture:corp"] to the grant.
  //
  // The 'tests' block runs without posture, so there's no checklist — watch the
  // matrix and the posture panel: only alice-macbook should keep SSH to prod.
  "postures": {
  },
  "groups": {
    "group:admin": ["alice@example.com", "bob@example.com"],
  },
  "tagOwners": {
    "tag:prod": ["group:admin"],
  },
  "grants": [
    { "src": ["group:admin"], "dst": ["tag:prod"], "ip": ["tcp:22"] },
  ],
}
